skip_64_Person(<<_:64, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, F@_3, F@_4, TrUserData) -> dfp_read_field_def_Person(Rest, Z1, Z2, F, F@_1, F@_2, F@_3, F@_4, TrUserData).

decode_msg_AddressBook(Bin, TrUserData) -> dfp_read_field_def_AddressBook(Bin, 0, 0, 0, id([], TrUserData), TrUserData).

dfp_read_field_def_AddressBook(<<10, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> d_field_AddressBook_people(Rest, Z1, Z2, F, F@_1, TrUserData);
dfp_read_field_def_AddressBook(<<>>, 0, 0, _, R1, TrUserData) ->
    S1 = #{},
    if R1 == '$undef' -> S1;
       true -> S1#{people => lists_reverse(R1, TrUserData)}
    end;
dfp_read_field_def_AddressBook(Other, Z1, Z2, F, F@_1, TrUserData) -> dg_read_field_def_AddressBook(Other, Z1, Z2, F, F@_1, TrUserData).

dg_read_field_def_AddressBook(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) when N < 32 - 7 -> dg_read_field_def_AddressBook(Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData);
dg_read_field_def_AddressBook(<<0:1, X:7, Rest/binary>>, N, Acc, _, F@_1, TrUserData) ->
    Key = X bsl N + Acc,
    case Key of
        10 -> d_field_AddressBook_people(Rest, 0, 0, 0, F@_1, TrUserData);
        _ ->
            case Key band 7 of
                0 -> skip_varint_AddressBook(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                1 -> skip_64_AddressBook(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                2 -> skip_length_delimited_AddressBook(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                3 -> skip_group_AddressBook(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                5 -> skip_32_AddressBook(Rest, 0, 0, Key bsr 3, F@_1, TrUserData)
            end
    end;
dg_read_field_def_AddressBook(<<>>, 0, 0, _, R1, TrUserData) ->
    S1 = #{},
    if R1 == '$undef' -> S1;
       true -> S1#{people => lists_reverse(R1, TrUserData)}
    end.

