    dfp_read_field_def_AddressBook(Rest, 0, Z2, FNum, F@_1, TrUserData).

skip_32_AddressBook(<<_:32, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> dfp_read_field_def_AddressBook(Rest, Z1, Z2, F, F@_1, TrUserData).

skip_64_AddressBook(<<_:64, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> dfp_read_field_def_AddressBook(Rest, Z1, Z2, F, F@_1, TrUserData).

'd_enum_Person.PhoneType'(0) -> 'MOBILE';
'd_enum_Person.PhoneType'(1) -> 'HOME';
'd_enum_Person.PhoneType'(2) -> 'WORK';
'd_enum_Person.PhoneType'(V) -> V.

read_group(Bin, FieldNum) ->
    {NumBytes, EndTagLen} = read_gr_b(Bin, 0, 0, 0, 0, FieldNum),
    <<Group:NumBytes/binary, _:EndTagLen/binary, Rest/binary>> = Bin,
    {Group, Rest}.

%% Like skipping over fields, but record the total length,
%% Each field is <(FieldNum bsl 3) bor FieldType> ++ <FieldValue>
%% Record the length because varints may be non-optimally encoded.
%%
%% Groups can be nested, but assume the same FieldNum cannot be nested
%% because group field numbers are shared with the rest of the fields
%% numbers. Thus we can search just for an group-end with the same
%% field number.
%%
%% (The only time the same group field number could occur would
%% be in a nested sub message, but then it would be inside a
%% length-delimited entry, which we skip-read by length.)
read_gr_b(<<1:1, X:7, Tl/binary>>, N, Acc, NumBytes, TagLen, FieldNum)
  when N < (32-7) ->
    read_gr_b(Tl, N+7, X bsl N + Acc, NumBytes, TagLen+1, FieldNum);
read_gr_b(<<0:1, X:7, Tl/binary>>, N, Acc, NumBytes, TagLen,
          FieldNum) ->
    Key = X bsl N + Acc,
    TagLen1 = TagLen + 1,
    case {Key bsr 3, Key band 7} of
        {FieldNum, 4} -> % 4 = group_end
            {NumBytes, TagLen1};
        {_, 0} -> % 0 = varint
            read_gr_vi(Tl, 0, NumBytes + TagLen1, FieldNum);
        {_, 1} -> % 1 = bits64
            <<_:64, Tl2/binary>> = Tl,
            read_gr_b(Tl2, 0, 0, NumBytes + TagLen1 + 8, 0, FieldNum);
        {_, 2} -> % 2 = length_delimited
            read_gr_ld(Tl, 0, 0, NumBytes + TagLen1, FieldNum);
        {_, 3} -> % 3 = group_start
            read_gr_b(Tl, 0, 0, NumBytes + TagLen1, 0, FieldNum);
        {_, 4} -> % 4 = group_end
            read_gr_b(Tl, 0, 0, NumBytes + TagLen1, 0, FieldNum);
        {_, 5} -> % 5 = bits32
            <<_:32, Tl2/binary>> = Tl,
            read_gr_b(Tl2, 0, 0, NumBytes + TagLen1 + 4, 0, FieldNum)
    end.

read_gr_vi(<<1:1, _:7, Tl/binary>>, N, NumBytes, FieldNum)
  when N < (64-7) ->
    read_gr_vi(Tl, N+7, NumBytes+1, FieldNum);
read_gr_vi(<<0:1, _:7, Tl/binary>>, _, NumBytes, FieldNum) ->
    read_gr_b(Tl, 0, 0, NumBytes+1, 0, FieldNum).

read_gr_ld(<<1:1, X:7, Tl/binary>>, N, Acc, NumBytes, FieldNum)
  when N < (64-7) ->
    read_gr_ld(Tl, N+7, X bsl N + Acc, NumBytes+1, FieldNum);
read_gr_ld(<<0:1, X:7, Tl/binary>>, N, Acc, NumBytes, FieldNum) ->
    Len = X bsl N + Acc,
    NumBytes1 = NumBytes + 1,
    <<_:Len/binary, Tl2/binary>> = Tl,
    read_gr_b(Tl2, 0, 0, NumBytes1 + Len, 0, FieldNum).

merge_msgs(Prev, New, MsgName) when is_atom(MsgName) -> merge_msgs(Prev, New, MsgName, []).

merge_msgs(Prev, New, MsgName, Opts) ->
    TrUserData = proplists:get_value(user_data, Opts),
    case MsgName of
        'Person.PhoneNumber' -> 'merge_msg_Person.PhoneNumber'(Prev, New, TrUserData);
        'Person' -> merge_msg_Person(Prev, New, TrUserData);
        'AddressBook' -> merge_msg_AddressBook(Prev, New, TrUserData)
    end.

-compile({nowarn_unused_function,'merge_msg_Person.PhoneNumber'/3}).
'merge_msg_Person.PhoneNumber'(#{} = PMsg, #{number := NFnumber} = NMsg, _) ->
    S1 = #{number => NFnumber},
    case {PMsg, NMsg} of
        {_, #{type := NFtype}} -> S1#{type => NFtype};
        {#{type := PFtype}, _} -> S1#{type => PFtype};
        _ -> S1
    end.

-compile({nowarn_unused_function,merge_msg_Person/3}).
merge_msg_Person(#{} = PMsg, #{name := NFname, id := NFid} = NMsg, TrUserData) ->
    S1 = #{name => NFname, id => NFid},
    S2 = case {PMsg, NMsg} of
             {_, #{email := NFemail}} -> S1#{email => NFemail};
             {#{email := PFemail}, _} -> S1#{email => PFemail};
             _ -> S1
         end,
    case {PMsg, NMsg} of
        {#{phones := PFphones}, #{phones := NFphones}} -> S2#{phones => 'erlang_++'(PFphones, NFphones, TrUserData)};
        {_, #{phones := NFphones}} -> S2#{phones => NFphones};
        {#{phones := PFphones}, _} -> S2#{phones => PFphones};
        {_, _} -> S2
    end.

-compile({nowarn_unused_function,merge_msg_AddressBook/3}).
merge_msg_AddressBook(PMsg, NMsg, TrUserData) ->
    S1 = #{},
    case {PMsg, NMsg} of
        {#{people := PFpeople}, #{people := NFpeople}} -> S1#{people => 'erlang_++'(PFpeople, NFpeople, TrUserData)};
        {_, #{people := NFpeople}} -> S1#{people => NFpeople};
        {#{people := PFpeople}, _} -> S1#{people => PFpeople};
        {_, _} -> S1
    end.


verify_msg(Msg, MsgName) when is_atom(MsgName) -> verify_msg(Msg, MsgName, []).

verify_msg(Msg, MsgName, Opts) ->
    TrUserData = proplists:get_value(user_data, Opts),
    case MsgName of
        'Person.PhoneNumber' -> 'v_msg_Person.PhoneNumber'(Msg, [MsgName], TrUserData);
        'Person' -> v_msg_Person(Msg, [MsgName], TrUserData);
        'AddressBook' -> v_msg_AddressBook(Msg, [MsgName], TrUserData);
        _ -> mk_type_error(not_a_known_message, Msg, [])
    end.


-compile({nowarn_unused_function,'v_submsg_Person.PhoneNumber'/3}).
-dialyzer({nowarn_function,'v_submsg_Person.PhoneNumber'/3}).
'v_submsg_Person.PhoneNumber'(Msg, Path, TrUserData) -> 'v_msg_Person.PhoneNumber'(Msg, Path, TrUserData).

-compile({nowarn_unused_function,'v_msg_Person.PhoneNumber'/3}).
-dialyzer({nowarn_function,'v_msg_Person.PhoneNumber'/3}).
'v_msg_Person.PhoneNumber'(#{number := F1} = M, Path, TrUserData) ->
    v_type_string(F1, [number | Path], TrUserData),
    case M of
        #{type := F2} -> 'v_enum_Person.PhoneType'(F2, [type | Path], TrUserData);
        _ -> ok
    end,
    lists:foreach(fun (number) -> ok;
                      (type) -> ok;
                      (OtherKey) -> mk_type_error({extraneous_key, OtherKey}, M, Path)
                  end,
                  maps:keys(M)),
    ok;
'v_msg_Person.PhoneNumber'(M, Path, _TrUserData) when is_map(M) -> mk_type_error({missing_fields, [number] -- maps:keys(M), 'Person.PhoneNumber'}, M, Path);
'v_msg_Person.PhoneNumber'(X, Path, _TrUserData) -> mk_type_error({expected_msg, 'Person.PhoneNumber'}, X, Path).

-compile({nowarn_unused_function,v_submsg_Person/3}).
-dialyzer({nowarn_function,v_submsg_Person/3}).
v_submsg_Person(Msg, Path, TrUserData) -> v_msg_Person(Msg, Path, TrUserData).

-compile({nowarn_unused_function,v_msg_Person/3}).
-dialyzer({nowarn_function,v_msg_Person/3}).
v_msg_Person(#{name := F1, id := F2} = M, Path, TrUserData) ->
    v_type_string(F1, [name | Path], TrUserData),
    v_type_int32(F2, [id | Path], TrUserData),
    case M of
        #{email := F3} -> v_type_string(F3, [email | Path], TrUserData);
        _ -> ok
    end,
    case M of
        #{phones := F4} ->
            if is_list(F4) ->
                   _ = ['v_submsg_Person.PhoneNumber'(Elem, [phones | Path], TrUserData) || Elem <- F4],
                   ok;
               true -> mk_type_error({invalid_list_of, {msg, 'Person.PhoneNumber'}}, F4, [phones | Path])
            end;
        _ -> ok
    end,
    lists:foreach(fun (name) -> ok;
                      (id) -> ok;
                      (email) -> ok;
                      (phones) -> ok;
                      (OtherKey) -> mk_type_error({extraneous_key, OtherKey}, M, Path)
                  end,
                  maps:keys(M)),
    ok;
v_msg_Person(M, Path, _TrUserData) when is_map(M) -> mk_type_error({missing_fields, [name, id] -- maps:keys(M), 'Person'}, M, Path);
v_msg_Person(X, Path, _TrUserData) -> mk_type_error({expected_msg, 'Person'}, X, Path).

-compile({nowarn_unused_function,v_msg_AddressBook/3}).
-dialyzer({nowarn_function,v_msg_AddressBook/3}).
v_msg_AddressBook(#{} = M, Path, TrUserData) ->
    case M of
        #{people := F1} ->
            if is_list(F1) ->
                   _ = [v_submsg_Person(Elem, [people | Path], TrUserData) || Elem <- F1],
                   ok;
               true -> mk_type_error({invalid_list_of, {msg, 'Person'}}, F1, [people | Path])
            end;
        _ -> ok
    end,
    lists:foreach(fun (people) -> ok;
                      (OtherKey) -> mk_type_error({extraneous_key, OtherKey}, M, Path)
                  end,
                  maps:keys(M)),
    ok;
v_msg_AddressBook(M, Path, _TrUserData) when is_map(M) -> mk_type_error({missing_fields, [] -- maps:keys(M), 'AddressBook'}, M, Path);
v_msg_AddressBook(X, Path, _TrUserData) -> mk_type_error({expected_msg, 'AddressBook'}, X, Path).

-compile({nowarn_unused_function,'v_enum_Person.PhoneType'/3}).
-dialyzer({nowarn_function,'v_enum_Person.PhoneType'/3}).
'v_enum_Person.PhoneType'('MOBILE', _Path, _TrUserData) -> ok;
'v_enum_Person.PhoneType'('HOME', _Path, _TrUserData) -> ok;
'v_enum_Person.PhoneType'('WORK', _Path, _TrUserData) -> ok;
'v_enum_Person.PhoneType'(V, _Path, _TrUserData) when -2147483648 =< V, V =< 2147483647, is_integer(V) -> ok;
'v_enum_Person.PhoneType'(X, Path, _TrUserData) -> mk_type_error({invalid_enum, 'Person.PhoneType'}, X, Path).

-compile({nowarn_unused_function,v_type_int32/3}).
-dialyzer({nowarn_function,v_type_int32/3}).
v_type_int32(N, _Path, _TrUserData) when is_integer(N), -2147483648 =< N, N =< 2147483647 -> ok;
v_type_int32(N, Path, _TrUserData) when is_integer(N) -> mk_type_error({value_out_of_range, int32, signed, 32}, N, Path);
v_type_int32(X, Path, _TrUserData) -> mk_type_error({bad_integer, int32, signed, 32}, X, Path).

-compile({nowarn_unused_function,v_type_string/3}).
-dialyzer({nowarn_function,v_type_string/3}).
v_type_string(S, Path, _TrUserData) when is_list(S); is_binary(S) ->
    try unicode:characters_to_binary(S) of
        B when is_binary(B) -> ok;
        {error, _, _} -> mk_type_error(bad_unicode_string, S, Path)
    catch
        error:badarg -> mk_type_error(bad_unicode_string, S, Path)
    end;
v_type_string(X, Path, _TrUserData) -> mk_type_error(bad_unicode_string, X, Path).

-compile({nowarn_unused_function,mk_type_error/3}).
-spec mk_type_error(_, _, list()) -> no_return().
mk_type_error(Error, ValueSeen, Path) ->
    Path2 = prettify_path(Path),
    erlang:error({gpb_type_error, {Error, [{value, ValueSeen}, {path, Path2}]}}).


-compile({nowarn_unused_function,prettify_path/1}).
-dialyzer({nowarn_function,prettify_path/1}).
prettify_path([]) -> top_level;
prettify_path(PathR) -> lists:append(lists:join(".", lists:map(fun atom_to_list/1, lists:reverse(PathR)))).


-compile({nowarn_unused_function,id/2}).
-compile({inline,id/2}).
id(X, _TrUserData) -> X.

-compile({nowarn_unused_function,v_ok/3}).
-compile({inline,v_ok/3}).
v_ok(_Value, _Path, _TrUserData) -> ok.

-compile({nowarn_unused_function,m_overwrite/3}).
-compile({inline,m_overwrite/3}).
m_overwrite(_Prev, New, _TrUserData) -> New.

-compile({nowarn_unused_function,cons/3}).
-compile({inline,cons/3}).
cons(Elem, Acc, _TrUserData) -> [Elem | Acc].

-compile({nowarn_unused_function,lists_reverse/2}).
-compile({inline,lists_reverse/2}).
'lists_reverse'(L, _TrUserData) -> lists:reverse(L).
-compile({nowarn_unused_function,'erlang_++'/3}).
-compile({inline,'erlang_++'/3}).
'erlang_++'(A, B, _TrUserData) -> A ++ B.


get_msg_defs() ->
    [{{enum, 'Person.PhoneType'}, [{'MOBILE', 0}, {'HOME', 1}, {'WORK', 2}]},
     {{msg, 'Person.PhoneNumber'},
      [#{name => number, fnum => 1, rnum => 2, type => string, occurrence => required, opts => []}, #{name => type, fnum => 2, rnum => 3, type => {enum, 'Person.PhoneType'}, occurrence => optional, opts => [{default, 'HOME'}]}]},
     {{msg, 'Person'},
      [#{name => name, fnum => 1, rnum => 2, type => string, occurrence => required, opts => []},
       #{name => id, fnum => 2, rnum => 3, type => int32, occurrence => required, opts => []},
       #{name => email, fnum => 3, rnum => 4, type => string, occurrence => optional, opts => []},
       #{name => phones, fnum => 4, rnum => 5, type => {msg, 'Person.PhoneNumber'}, occurrence => repeated, opts => []}]},
     {{msg, 'AddressBook'}, [#{name => people, fnum => 1, rnum => 2, type => {msg, 'Person'}, occurrence => repeated, opts => []}]}].


get_msg_names() -> ['Person.PhoneNumber', 'Person', 'AddressBook'].


get_group_names() -> [].


get_msg_or_group_names() -> ['Person.PhoneNumber', 'Person', 'AddressBook'].


get_enum_names() -> ['Person.PhoneType'].


fetch_msg_def(MsgName) ->
    case find_msg_def(MsgName) of
        Fs when is_list(Fs) -> Fs;
        error -> erlang:error({no_such_msg, MsgName})
    end.


fetch_enum_def(EnumName) ->
    case find_enum_def(EnumName) of
        Es when is_list(Es) -> Es;
        error -> erlang:error({no_such_enum, EnumName})
